        target_idx = min(range(len(self.time_grid)), key=lambda i: abs(self.time_grid[i]-target_time))
        if target_idx <= current_idx:
            raise InvalidActionError('nonadvance')
        self._charge(target_idx-current_idx)
        p['time'] = self.time_grid[target_idx]
        if p['time'] >= 1.0:
            p['status'] = 'completed'
        return self.get_state().particles[particle_id]

