        self._previews[aid] = rec
        p['last_preview_id'] = aid
        return rec

    def backward(self, anchor_id, target_time, noise_policy='fresh_noise', num_children=1, mask=None, strength=1.0):
        ids = []
        for _ in range(num_children):
            pid = self._next_pid
            self._next_pid += 1
            self._particles[pid] = {'time': max([t for t in self.time_grid if t <= target_time]), 'status': 'active', 'last_preview_id': None, 'source_anchor_id': anchor_id}
            ids.append(pid)
        return ids

    def prune(self, particle_ids):
        for pid in particle_ids:
            if self._particles[pid]['status'] == 'completed':
                raise InvalidActionError('completed')
            self._particles[pid]['status'] = 'pruned'

