        if rule == 'best_preview_score' and self._previews:
            best = max(self._previews.values(), key=lambda p: p.score)
            return AnswerRecord(particle_id=best.particle_id, preview_id=best.id, latent=(), reward=best.score, nfe_used=self.budget-self._budget_left, rule=rule, event_log=[], score_dict=best.score_dict)
        active = [pid for pid,p in self._particles.items() if p['status'] in {'active','completed'}]
        return AnswerRecord(particle_id=active[-1] if active else None, preview_id=None, latent=(), reward=None, nfe_used=self.budget-self._budget_left, rule=rule, event_log=[], score_dict={})

    def get_state(self):
        particles = {}
        for pid,p in self._particles.items():
            particles[pid] = ParticleSummary(id=pid, time=p['time'], parent_id=None, source_anchor_id=p['source_anchor_id'], nfe_used=0, status=p['status'], last_preview_id=p['last_preview_id'], num_children=0)
        return ControllerState(prompt='fake', budget_left=self._budget_left, active_particle_ids=[pid for pid,p in self._particles.items() if p['status']=='active'], completed_particle_ids=[pid for pid,p in self._particles.items() if p['status']=='completed'], pruned_particle_ids=[pid for pid,p in self._particles.items() if p['status']=='pruned'], particles=particles, previews=dict(self._previews), event_log=[])

controller = OptimalController()
